package pagos;
import com.fasterxml.jackson.databind.*;import config.ConfiguracionMercadoPago;import java.util.*;
public final class PreflightMercadoPago {private final MercadoPagoHttpTransport http;private final ObjectMapper json;public PreflightMercadoPago(){this(new JdkMercadoPagoHttpTransport(),new ObjectMapper().findAndRegisterModules());}public PreflightMercadoPago(MercadoPagoHttpTransport h,ObjectMapper j){if(h==null||j==null)throw new IllegalArgumentException("El transporte y JSON son obligatorios.");http=h;json=j;}public Resultado verificar(ConfiguracionMercadoPago c){if(c==null||!c.disponible())return new Resultado(false,"NO_CONFIGURADO");if(!c.sandbox())return new Resultado(true,"PRODUCCION_CONFIGURADA");if(c.testUserId()==null||c.testUserId().isBlank())return new Resultado(false,"VENDEDOR_PRUEBA_AUSENTE");try{var r=http.ejecutar("GET",c.apiBaseUrl().resolve("/users/me"),Map.of("Authorization","Bearer "+c.accessToken(),"Accept","application/json"),null);if(!r.exitosa())return new Resultado(false,"HTTP_"+r.estado());JsonNode n=json.readTree(r.cuerpo());JsonNode id=n.get("id");if(id==null||id.isNull()||id.asText().isBlank())return new Resultado(false,"IDENTIDAD_INCOMPLETA");return new Resultado(c.testUserId().equals(id.asText()),c.testUserId().equals(id.asText())?"SANDBOX_VERIFICADO":"IDENTIDAD_NO_COINCIDE");}catch(RuntimeException e){return new Resultado(false,"NO_VERIFICADO");}catch(Exception e){return new Resultado(false,"RESPUESTA_INVALIDA");}}public record Resultado(boolean valido,String estado){}}
